import{z as l,x as i,o,c as d,q as B,j as n,D as A,d as a,s as r,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"数据库内核实践收束","description":"","frontmatter":{"title":"数据库内核实践收束","date":"2026-09-18T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dbk-map.md","filePath":"cs/dbk-map.md","lastUpdated":1791063341000}'),p={name:"cs/dbk-map.md"};function c(C,E,m,D,u,F){const t=i("Mermaid");return o(),d("div",null,[E[2]||(E[2]=B('<h1 id="数据库内核实践收束" tabindex="-1">数据库内核实践收束 <a class="header-anchor" href="#数据库内核实践收束" aria-label="Permalink to &quot;数据库内核实践收束&quot;">​</a></h1><div class="epigraph"><p>引擎不是六个组件的堆叠，是一条写路径上六个契约的接力；读懂一条 UPDATE 从 SQL 到盘上字节的全程，就读懂了内核。</p><footer>—— 据 Hellerstein, Stonebraker and Hamilton, *Architecture of a Database System*, 2007；Gray and Reuter, *Transaction Processing*, 1993 整理</footer></div><p><a href="/cs/dbk-wal-implementation">上一课</a>把提交序兑现成盘上的日志字节。本课收束「数据库内核实践」课程：把六课的组件接回一条写路径，看不变量各自放在哪一层，再给出读真实引擎源码的入口。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>收束要回答的不是新知识，而是组装：六课各立了一份契约——页与缓冲池的 fix/unpin 与「持 pin 不做 I/O」、树闩的全序、LSM 的不可变文件与序号全序、执行器的 open/next/close、事务管理器的两本账、日志机的 pageLSN 不等式——它们如何在一次 UPDATE 里咬合？分开看都对、拼起来会错在哪：不变量放错层。把页闩持有到提交，纯读开始互相阻塞；把事务锁做成全序获取，业务等待关系根本不服从；把刷页次序交给操作系统，它不认识 pageLSN。每层契约的边界感，是组装时最贵的东西。</p><p><span class="marginnote">「契约接力」可以想成医院交接班：执行器把病人（一行数据）交给事务科盖章（拿锁），事务科交给缓冲科安排床位（fix 页），缓冲科动笔前必须先让日志科挂号（WAL）。每一棒只认上一棒的手续，谁也不越权重办。</span></p><h3 id="一条-update-的全程" tabindex="-1">一条 UPDATE 的全程 <a class="header-anchor" href="#一条-update-的全程" aria-label="Permalink to &quot;一条 UPDATE 的全程&quot;">​</a></h3><p><code>UPDATE accounts SET bal = bal - 1 WHERE id = 7</code> 依次穿过：执行器的算子树——索引探测沿 B+ 树蟹行（树闩，微秒级持有），扫描吐出可见行；事务管理器——领事务、查写冲突、对目标行拿写锁（毫秒到秒级持有，直到提交或回滚）；存储层——fix 目标页进缓冲池（pin）；日志机——改页之前先追加一条 UPDATE 记录进缓冲；缓冲池——改页、页头记 pageLSN、unpin；提交——组提交队列一次 fsync，应答返回，锁释放，新版本对后到的快照可见。六个环节、六个契约、一条路径，没有一处旁路。</p><p><span class="marginnote">读源码可以按组件直接进门：PostgreSQL 的 <code>src/backend/storage/buffer</code> 与 <code>access/transam/xlog</code>；InnoDB 的 <code>buf0buf</code>、<code>btr0btr</code>、<code>trx0trx</code>、<code>log0log</code>；SQLite 的 <code>pager.c</code> 与 <code>wal.c</code>；RocksDB 的 <code>VersionSet</code> 与 <code>MemTableList</code>。文件名不同，契约相同。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把六课压缩成一张不变量分层表：物理形状的不变量归闩——短持有、全序获取、不与 I/O 同持，守的是树与页的正确性；逻辑内容的不变量归锁与快照——长持有、可死锁要检测，守的是事务的正确性；持久性不变量归日志——顺序写、先日志后页，守的是崩溃的正确性。再用这张表读三种真实引擎：PostgreSQL 是「堆页加全套 ARIES」的教科书实现；InnoDB 把堆换成索引组织表、把 MVCC 版本收进 undo 段；RocksDB 把整个存储换成 LSM，锁与日志的接口几乎不动。组件边界稳，替换内部实现就不伤及邻层——这正是这门课把组件拆开写一遍的回报。</p>',11)),(o(),n(s,null,{default:A(()=>[r(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQL%5B%22UPDATE%20%E8%AF%AD%E5%8F%A5%22%5D%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%E5%99%A8%EF%BC%9A%E7%AE%97%E5%AD%90%E6%A0%91%E4%B8%8E%E9%A2%84%E7%AE%97%22%5D%0A%20%20EX%20--%3E%20TX%5B%22%E4%BA%8B%E5%8A%A1%E7%AE%A1%E7%90%86%E5%99%A8%EF%BC%9A%E9%94%81%E4%B8%8E%E5%BF%AB%E7%85%A7%22%5D%0A%20%20TX%20--%3E%20BP%5B%22%E7%BC%93%E5%86%B2%E6%B1%A0%EF%BC%9Afix%20%E9%A1%B5%22%5D%0A%20%20BP%20--%3E%20WM%5B%22%E6%97%A5%E5%BF%97%E6%9C%BA%EF%BC%9A%E5%85%88%E8%AE%B0%E6%97%A5%E5%BF%97%22%5D%0A%20%20WM%20--%3E%20MUT%5B%22%E6%94%B9%E9%A1%B5%EF%BC%8C%E8%AE%B0%20pageLSN%22%5D%0A%20%20MUT%20--%3E%20CMT%5B%22%E6%8F%90%E4%BA%A4%EF%BC%9Afsync%EF%BC%8C%E5%BA%94%E7%AD%94%EF%BC%8C%E6%94%BE%E9%94%81%22%5D%0A%20%20CMT%20--%3E%20DISK%5B%22%E9%A1%B5%E6%8C%89%E8%87%AA%E5%B7%B1%E7%9A%84%E8%8A%82%E5%A5%8F%E8%90%BD%E7%9B%98%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("本课程的机制主线只有一条："),e("strong",null,"每层用最短的持有时间保护最局部的正确性，把长的、跨语句的正确性上交"),a("。闩管微秒，锁管事务，日志管永久；向上每层不重复下一层的工作，只引用它的契约。反例全部来自层间越权：在闩层做死锁检测（不必，全序免疫）；在锁层管页的物理互斥（锁太粗，并发立刻塌）；用 mmap 把刷盘次序交给页缓存（它不认识日志序）。副线也值得带走：迭代器与「不可变文件加原子切换」是贯穿全课的两种通用件——执行器栈在迭代器上，LSM 的 manifest 在原子切换上；认出这两种模式，读任何新引擎的源码都有把手。")],-1)),E[5]||(E[5]=e("p",null,"三类不变量各归哪层、持有多久：",-1)),(o(),n(s,null,{default:A(()=>[r(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E4%B8%80%E4%B8%AA%E4%B8%8D%E5%8F%98%E9%87%8F%E8%AF%A5%E8%B0%81%E5%AE%88%EF%BC%9F%22%5D%20--%3E%20PHYS%5B%22%E7%89%A9%E7%90%86%E5%BD%A2%E7%8A%B6%EF%BC%9A%E9%A1%B5%E4%B8%8E%E6%8C%87%E9%92%88%22%5D%0A%20%20PHYS%20--%3E%20PL%5B%22%E6%A0%91%E9%97%A9%EF%BC%9A%E5%BE%AE%E7%A7%92%E7%BA%A7%EF%BC%8C%E5%90%91%E4%B8%8B%E5%90%91%E5%8F%B3%E5%85%A8%E5%BA%8F%22%5D%0A%20%20Q%20--%3E%20LOGIC%5B%22%E9%80%BB%E8%BE%91%E5%86%85%E5%AE%B9%EF%BC%9A%E8%A1%8C%E4%B8%8E%E9%94%AE%E5%8C%BA%E9%97%B4%22%5D%0A%20%20LOGIC%20--%3E%20LK%5B%22%E4%BA%8B%E5%8A%A1%E9%94%81%E4%B8%8E%E5%BF%AB%E7%85%A7%EF%BC%9A%E6%8C%81%E5%88%B0%E6%8F%90%E4%BA%A4%EF%BC%8C%E5%8F%AF%E6%AD%BB%E9%94%81%E8%A6%81%E6%A3%80%E6%B5%8B%22%5D%0A%20%20Q%20--%3E%20DUR%5B%22%E6%8C%81%E4%B9%85%E6%80%A7%EF%BC%9A%E5%B4%A9%E6%BA%83%E5%90%8E%E4%BB%8D%E5%9C%A8%22%5D%0A%20%20DUR%20--%3E%20WALC%5B%22%E6%97%A5%E5%BF%97%E6%9C%BA%EF%BC%9A%E5%85%88%E6%97%A5%E5%BF%97%E5%90%8E%E9%A1%B5%EF%BC%8C%E9%A1%BA%E5%BA%8F%E5%86%99%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<p><span class="marginnote">mmap 就是请操作系统把文件当内存用：省掉一次拷贝，但淘汰与写回全听内核的。初学者容易当它是白赚的优化——实际内核不认识 pageLSN，可能把数据页先于日志刷进盘；崩溃后这条页就是一笔无凭据的账，恢复逻辑直接作废。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程刻意不覆盖：查询优化与计划缓存，是查询优化深化课的地界；分布式事务、共识与分片，在主干与分布式深化课；列存与分析执行、各类专用索引也未入。单机事务型内核的地基到此为止——再往上，是优化器在计划空间里选路，是集群把日志传给副本。</p><p><span class="marginnote">这个收尾方向如果想反了——比如把「分布式」当成单机没做好的补丁——后面读共识与分片就会处处别扭。单机内核是地基不是残缺品：副本之间同步的正是这里的日志，分片切的正是这里的键空间。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>六个契约一条路径：执行器、事务、缓冲池、日志、页、提交，无一处旁路。</li><li>不变量分层：闩管形状（短、全序），锁与快照管内容（长、可检测），日志管持久（先日志后页）。</li><li>层间越权是组装的头号事故：混闩与锁、让 OS 决定刷盘次序都属此类。</li><li>迭代器与「不可变加原子切换」是可迁移的通用件，读源码先找它们。</li><li>出处：Hellerstein, Stonebraker and Hamilton, 2007；Gray and Reuter, 1993；PostgreSQL、InnoDB、SQLite、RocksDB 源码树。</li></ul>',6))])}const b=l(p,[["render",c]]);export{S as __pageData,b as default};
